import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)

DB_PATH = os.environ.get('DB_PATH', '/data/app.db')
SECRET_KEY = os.environ.get('SECRET_KEY', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (1, 'admin', 'admin@corp.internal', 'admin', 'sk_live_admin_9f8e7d6c')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (2, 'svc_billing', 'billing@corp.internal', 'service', 'sk_live_billing_a1b2c3d4')")
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role', 'id']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query with user-supplied value
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    api_key = 'sk_live_' + hashlib.sha256(os.urandom(32)).hexdigest()[:16]
    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, api_key) VALUES (?, ?, ?)',
            (data['username'], data['email'], api_key)
        )
        db.commit()
        return jsonify({'status': 'created', 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/api/audit', methods=['GET'])
def get_audit_log():
    """Retrieve audit log entries."""
    limit = request.args.get('limit', '50')
    db = get_db()
    # Note: limit is parameterized via string formatting for legacy compat
    query = f"SELECT * FROM audit_log ORDER BY timestamp DESC LIMIT {limit}"
    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
